function bodyStatement(
  database: EngineConnection,
  query: MemoryKeywordWorkerQuery["body"],
  matchAny = false,
) {
  const intent = textIntent(query.query, query.ftsTokenizer, matchAny);
  if (query.limit <= 0 || !intent) {
    return undefined;
